const val GLOW_SHADER = """""
    uniform float2 resolution;
    uniform float progress; 
    uniform float3 color; 

    half4 main(float2 coords) {
        float2 center = resolution * 0.5;
        float dist = distance(coords, center);
        float maxRadius = resolution.x * 0.6;
        float glow = 1.0 - smoothstep(0.0, maxRadius, dist);
        glow = glow * glow;
        float alpha = glow * progress * 0.4;
        return half4(color, alpha);
    }
"""""

@RequiresApi(TIRAMISU)
@Composable
fun AgslGradientBackground(
    modifier: Modifier = Modifier,
    topGradientColor: Color,
    bottomGradientColor: Color,
    content: @Composable BoxScope.() -> Unit
) {
    val shader = remember { RuntimeShader(GradientShaderSource) }

    val shaderBrush = remember(shader, topGradientColor, bottomGradientColor) {
        shader.setColorUniform("topColor", topGradientColor.toArgb())
        shader.setColorUniform("bottomColor", bottomGradientColor.toArgb())
        ShaderBrush(shader)
    }

    Box(
        modifier = modifier
            .fillMaxSize()
            .drawBehind {
                shader.setFloatUniform("resolution", size.width, size.height)
                drawRect(shaderBrush)
            },
        content = content
    )
}

@Language("AGSL")
private const val GradientShaderSource = """""
    uniform float2 resolution;
    layout(color) uniform half4 topColor;
    layout(color) uniform half4 bottomColor;

    half4 main(float2 fragCoord) {
        float y = fragCoord.y / resolution.y;
        // Add a slight curve to the gradient for a more natural look
        y = smoothstep(0.0, 1.0, y);
        return mix(topColor, bottomColor, y);
    }
"""""

@Composable
fun EnvironmentControls(modifier: Modifier = Modifier) {
    val activity = LocalActivity.current
    val session = LocalSession.current
    if (session != null && activity is ComponentActivity) {
        val uiIsSpatialized = LocalSpatialCapabilities.current.isSpatialUiEnabled
        val environmentController = remember(activity) {
            EnvironmentController(session, activity.lifecycleScope)
        }
        val environmentModelName = "green_hills_ktx2_mipmap.glb"
        environmentController.loadModelAsset(environmentModelName)

        Surface(modifier.clip(CircleShape)) {
            Column(Modifier.width(IntrinsicSize.Min)) {
                if (uiIsSpatialized) {
                    SetVirtualEnvironmentButton {
                        environmentController.requestCustomEnvironment(
                            environmentModelName
                        )
                    }
                    SetPassthroughButton { environmentController.requestPassthrough() }
                    RequestHomeSpaceButton { environmentController.requestHomeSpaceMode() }
                } else {
                    RequestFullSpaceButton { environmentController.requestFullSpaceMode() }
                }
            }
        }
    }
}

